ALTER TABLE "app"."notifications" ADD CONSTRAINT "notification_target" CHECK ((("app"."notifications"."kind" = 'otp' AND "app"."notifications"."challenge_id" IS NOT NULL AND "app"."notifications"."booking_id" IS NULL AND "app"."notifications"."booking_version" IS NULL AND "app"."notifications"."scheduled_at" IS NULL) OR ("app"."notifications"."kind" IN ('confirmation','reminder','received','in_progress','completed') AND "app"."notifications"."challenge_id" IS NULL AND "app"."notifications"."booking_id" IS NOT NULL AND "app"."notifications"."booking_version" IS NOT NULL AND "app"."notifications"."booking_version" > 0 AND "app"."notifications"."scheduled_at" IS NOT NULL)) AND "app"."notifications"."invoice_id" IS NULL AND "app"."notifications"."request_key" IS NULL AND "app"."notifications"."requested_by" IS NULL AND "app"."notifications"."recipient_phone" IS NULL OR ("app"."notifications"."kind"='invoice' AND "app"."notifications"."invoice_id" IS NOT NULL AND "app"."notifications"."request_key" IS NOT NULL AND "app"."notifications"."requested_by" IS NOT NULL AND "app"."notifications"."recipient_phone" ~ '^[+]628[0-9]{8,11}$' AND "app"."notifications"."recipient_phone" IS NOT NULL AND "app"."notifications"."challenge_id" IS NULL AND "app"."notifications"."booking_id" IS NULL AND "app"."notifications"."booking_version" IS NULL AND "app"."notifications"."scheduled_at" IS NULL));